import{_ as a,o as r,c as o,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"参数页：调数值","description":"","frontmatter":{},"headers":[],"relativePath":"use/params-page.md","filePath":"use/params-page.md","lastUpdated":null}'),d={name:"use/params-page.md"};function s(l,t,i,n,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="参数页-调数值" tabindex="-1">参数页：调数值 <a class="header-anchor" href="#参数页-调数值" aria-label="Permalink to &quot;参数页：调数值&quot;">​</a></h1><p><strong>控制台第一页，也是用得最多的一页。</strong> 所有数值调整都在这里。</p><h2 id="页面上有什么" tabindex="-1">页面上有什么 <a class="header-anchor" href="#页面上有什么" aria-label="Permalink to &quot;页面上有什么&quot;">​</a></h2><p>从上到下：</p><ol><li><strong>分组标题</strong>（可展开/收起）</li><li><strong>参数行</strong> —— 每行一个参数：名称、当前值、滑块</li><li><strong>一键预设按钮</strong>（部分参数有）</li><li><strong>粘贴导入分享码</strong> 按钮</li><li><strong>恢复默认</strong> 按钮</li></ol><h2 id="怎么调一个参数" tabindex="-1">怎么调一个参数 <a class="header-anchor" href="#怎么调一个参数" aria-label="Permalink to &quot;怎么调一个参数&quot;">​</a></h2><h3 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h3><p><strong>拖滑块</strong> → 数值实时变化。</p><p>倍率类参数默认 <code>1.0</code>：</p><ul><li>往<strong>右</strong>拖 = 增强（&gt; 1.0）</li><li>往<strong>左</strong>拖 = 减弱（&lt; 1.0）</li></ul><p>开关类参数默认 <code>0</code>：</p><ul><li><code>0</code> = 关闭</li><li><code>1</code> = 开启</li></ul><h3 id="生效时机" tabindex="-1">生效时机 <a class="header-anchor" href="#生效时机" aria-label="Permalink to &quot;生效时机&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">必须重开游戏</p><p>参数在<strong>游戏启动时读取一次</strong>。拖动滑块只改配置，<strong>不会立刻生效</strong>。</p><p>流程：<strong>调 → 完全退出游戏 → 重开 → 生效。</strong></p><p>「完全退出」是从后台任务里划掉，不是按 Home 键。</p></div><h2 id="分组管理" tabindex="-1">分组管理 <a class="header-anchor" href="#分组管理" aria-label="Permalink to &quot;分组管理&quot;">​</a></h2><p>参数按功能分组，方便找到你要的那个：</p><table tabindex="0"><thead><tr><th>分组</th><th>包含</th></tr></thead><tbody><tr><td>战斗</td><td>主炮、鱼雷、航弹、反潜</td></tr><tr><td>环境</td><td>风的影响</td></tr><tr><td>感知</td><td>声呐、雷达</td></tr><tr><td>航空</td><td>舰载机</td></tr><tr><td>经济</td><td>威望、修理</td></tr><tr><td>AI</td><td>敌方反应</td></tr><tr><td>沙盒</td><td>调试开关</td></tr><tr><td>联机</td><td>本地热座</td></tr><tr><td>调试</td><td>日志开关</td></tr></tbody></table><h3 id="展开-收起" tabindex="-1">展开 / 收起 <a class="header-anchor" href="#展开-收起" aria-label="Permalink to &quot;展开 / 收起&quot;">​</a></h3><p>点分组标题展开或收起。<strong>展开状态会被记住</strong>，下次打开面板还是这个样子。</p><h3 id="全部展开-收起" tabindex="-1">全部展开 / 收起 <a class="header-anchor" href="#全部展开-收起" aria-label="Permalink to &quot;全部展开 / 收起&quot;">​</a></h3><p>页面上有「全部展开」「全部收起」按钮，一次处理所有分组。</p><div class="tip custom-block"><p class="custom-block-title">为什么要记住展开状态</p><p>因为参数多，每次重开面板都从全展开开始，找东西很累。</p><p>记住状态之后，你可以只展开常用的那几个分组，其他收着。</p></div><h2 id="一键预设" tabindex="-1">一键预设 <a class="header-anchor" href="#一键预设" aria-label="Permalink to &quot;一键预设&quot;">​</a></h2><p>某些参数提供<strong>快捷键</strong>，不用拖滑块：</p><table tabindex="0"><thead><tr><th>场景</th><th>典型预设</th></tr></thead><tbody><tr><td>开局威望</td><td>10 万 / 50 万 / 100 万</td></tr><tr><td>其他</td><td>视参数而定</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">预设值都经过边界校验</p><p>一键预设的所有值都<strong>在硬边界内</strong>，不会出现「点了预设却没生效」的情况。</p><p>（手写 mod.json 才需要担心边界问题，见 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a>。）</p></div><h2 id="恢复本组" tabindex="-1">恢复本组 <a class="header-anchor" href="#恢复本组" aria-label="Permalink to &quot;恢复本组&quot;">​</a></h2><p>每个分组可能带一个「<strong>恢复本组</strong>」按钮，把这个分组的所有参数还原成默认值。</p><p>比「恢复全部」更精细 —— 只想撤销某一组改动时用这个。</p><h2 id="恢复默认-全部" tabindex="-1">恢复默认（全部） <a class="header-anchor" href="#恢复默认-全部" aria-label="Permalink to &quot;恢复默认（全部）&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">这是两段确认操作</p><p>点一次会进入「确认」状态，再点一次才真的执行。</p><p><strong>而且切页或收起面板时，确认状态会自动清零</strong> —— 防止你点了一次、去干别的、回来手滑点到第二次。</p></div><p>「恢复默认」会：</p><ul><li>✅ 把<strong>所有参数</strong>清空回默认值</li><li>❌ <strong>不会</strong>删除你装的 Mod</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么 Mod 不会被删</p><p>因为操作对象不同：</p><table tabindex="0"><thead><tr><th>操作</th><th>影响</th></tr></thead><tbody><tr><td>参数页「恢复默认」</td><td>清空<strong>参数改动</strong></td></tr><tr><td>Mod 页「删除」</td><td>删掉<strong>Mod 文件夹</strong></td></tr></tbody></table><p>所以如果你装了 Mod A（它改了主炮伤害），点「恢复默认」后主炮确实回默认了，但<strong>下次重开游戏 Mod A 又生效了</strong>（因为 Mod 还在）。</p><p>想彻底停用 Mod，去 <a href="/AtlanticFleetSite/docs/use/mods-page">Mod 页</a> 禁用它。</p></div><h2 id="粘贴导入分享码" tabindex="-1">粘贴导入分享码 <a class="header-anchor" href="#粘贴导入分享码" aria-label="Permalink to &quot;粘贴导入分享码&quot;">​</a></h2><p>这里是<strong>装别人 Mod 的主要入口</strong>。</p><ol><li>点「粘贴导入分享码」</li><li>粘贴一串 <code>AFMOD1:…</code></li><li>确认</li><li><strong>完全退出游戏，重开</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">粘贴不进去怎么办</p><p>某些安卓设备对剪贴板有权限限制。可以尝试：</p><ul><li>长按输入框手动粘贴</li><li>用「Mod 页」的分享码相关功能</li><li>或者改用文件方式（丢进 <code>mods/_sharein/</code>）</li></ul><p>详见 <a href="/AtlanticFleetSite/docs/features/sharecode">Mod 分享码</a>。</p></div><h2 id="当前值怎么读" tabindex="-1">当前值怎么读 <a class="header-anchor" href="#当前值怎么读" aria-label="Permalink to &quot;当前值怎么读&quot;">​</a></h2><p>每个参数行会显示<strong>当前值</strong>。倍率类显示小数（<code>1.5</code>），开关类显示 <code>0/1</code>。</p><p>如果你不确定「这个值是不是我改的」，去 <a href="/AtlanticFleetSite/docs/use/status-page">状态页</a> —— 那里会列出<strong>所有偏离原版的参数</strong>，对比更直观。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="拖了滑块但没效果" tabindex="-1">拖了滑块但没效果 <a class="header-anchor" href="#拖了滑块但没效果" aria-label="Permalink to &quot;拖了滑块但没效果&quot;">​</a></h3><p><strong>重开游戏了吗？</strong> 这是最常见的原因。</p><h3 id="数值会自动跳回去" tabindex="-1">数值会自动跳回去 <a class="header-anchor" href="#数值会自动跳回去" aria-label="Permalink to &quot;数值会自动跳回去&quot;">​</a></h3><p>如果滑块拖不到你要的位置，说明那个位置<strong>超出了硬边界</strong>，被限制了。</p><p>看一下 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a> 里这个参数的硬边界。</p><h3 id="我改了很多-忘了改过什么" tabindex="-1">我改了很多，忘了改过什么 <a class="header-anchor" href="#我改了很多-忘了改过什么" aria-label="Permalink to &quot;我改了很多，忘了改过什么&quot;">​</a></h3><p>去 <a href="/AtlanticFleetSite/docs/use/status-page">状态页</a> 看偏离清单。</p><h3 id="想撤销一次改动" tabindex="-1">想撤销一次改动 <a class="header-anchor" href="#想撤销一次改动" aria-label="Permalink to &quot;想撤销一次改动&quot;">​</a></h3><ul><li>撤销<strong>一个分组</strong> → 该分组的「恢复本组」</li><li>撤销<strong>全部</strong> → 「恢复默认」</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>参数系统原理 → <a href="/AtlanticFleetSite/docs/features/params">参数系统</a></li><li>完整参数表 → <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a></li><li>看改过什么 → <a href="/AtlanticFleetSite/docs/use/status-page">状态页：看现场</a></li></ul>',53)])])}const g=a(d,[["render",s]]);export{u as __pageData,g as default};
